export const TEMPLATES=enrichSickBank(enrichBank(BANK));
const NATURAL=[0,2,4,5,7,9,11];
const LETTERS=['C','D','E','F','G','A','B'];
const SOLFEGE=['Do','Ré','Mi','Fa','Sol','La','Si'];
const FLAT_ROOT=['C','Db','D','Eb','E','F','Gb','G','Ab','A','Bb','B'];
const SHARP_ROOT=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
/** Orthographe basée sur le degré diatonique, y compris #9, b13 et bb7. */
export function spellNote(rootPc,interval,degree,solfege=false,preferFlats=true){
  const pc=((rootPc%12)+12)%12;
  const root=(preferFlats?FLAT_ROOT:SHARP_ROOT)[pc];
  const rootIndex=LETTERS.indexOf(root[0]);
  const match=String(degree).match(/\d+/);
  const degreeNumber=match?Number(match[0]):1;
  const targetIndex=(rootIndex+degreeNumber-1)%7;
  const targetPc=((pc+interval)%12+12)%12;
  let alteration=(targetPc-NATURAL[targetIndex]+18)%12-6;
  const sign=alteration<0?'♭'.repeat(-alteration):'♯'.repeat(alteration);
  return (solfege?SOLFEGE:LETTERS)[targetIndex]+sign;
}
